BEGIN;
CREATE TABLE IF NOT EXISTS regulatory_changes(id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,source_id TEXT NOT NULL,source_uri TEXT NOT NULL,publisher TEXT NOT NULL,jurisdiction TEXT NOT NULL,effective_at TIMESTAMPTZ NOT NULL,published_at TIMESTAMPTZ NOT NULL,retrieved_at TIMESTAMPTZ NOT NULL,source_version TEXT NOT NULL,content_digest TEXT NOT NULL,source_provenance JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'detected',version INTEGER NOT NULL DEFAULT 1,owner_id TEXT NOT NULL,assessor_id TEXT,approver_id TEXT,retain_until TIMESTAMPTZ,legal_hold BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,source_id,source_version,content_digest));
CREATE TABLE IF NOT EXISTS regulatory_impacts(id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,change_id UUID NOT NULL REFERENCES regulatory_changes(id),target_type TEXT NOT NULL CHECK(target_type IN('policy','control','product','contract','process','system')),target_id TEXT NOT NULL,owner_id TEXT NOT NULL,obligation TEXT NOT NULL,deadline TIMESTAMPTZ,risk_rating TEXT NOT NULL CHECK(risk_rating IN('low','medium','high','critical')),status TEXT NOT NULL DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS regulatory_citations(id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,change_id UUID NOT NULL REFERENCES regulatory_changes(id),source_uri TEXT NOT NULL,source_version TEXT NOT NULL,content_digest TEXT NOT NULL,locator TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(change_id,source_uri,source_version,content_digest,locator));
CREATE TABLE IF NOT EXISTS scenario_evaluations(id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,change_id UUID NOT NULL REFERENCES regulatory_changes(id),scenario_id TEXT NOT NULL,input_digest TEXT NOT NULL,passed BOOLEAN NOT NULL,result JSONB NOT NULL,evaluated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(change_id,scenario_id,input_digest));
CREATE TABLE IF NOT EXISTS regulatory_decisions(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,change_id UUID NOT NULL REFERENCES regulatory_changes(id),from_status TEXT,to_status TEXT NOT NULL,actor_id TEXT NOT NULL,actor_role TEXT NOT NULL,rationale TEXT NOT NULL,impact_snapshot JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION immutable_regulatory_decision() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'regulatory decisions are append-only';END$$;
DROP TRIGGER IF EXISTS regulatory_decisions_immutable ON regulatory_decisions;
CREATE TRIGGER regulatory_decisions_immutable BEFORE UPDATE OR DELETE ON regulatory_decisions FOR EACH ROW EXECUTE FUNCTION immutable_regulatory_decision();
CREATE INDEX IF NOT EXISTS regulatory_change_queue_idx ON regulatory_changes(tenant_id,status,effective_at);
CREATE INDEX IF NOT EXISTS regulatory_impact_deadline_idx ON regulatory_impacts(tenant_id,status,deadline);
COMMIT;
